INSERT INTO parks (name, lat, lon, region) SELECT 'Six Flags Qiddiya City', 24.5868, 46.3311, 'Saudi Arabia' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Six Flags Qiddiya City');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Adrena-Line', 'Six Flags Qiddiya City', 'Steel', 'Vekoma', 'Vekoma Suspended Family Coaster', 65.6, 44.7, 1620.7, 0, NULL, 2025, '2025-12-31', 'day', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Adrena-Line' AND park = 'Six Flags Qiddiya City');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Adrena-Line' AND c.park = 'Six Flags Qiddiya City' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
